export const APP = "import {createGram,addTrace,addTension,selectFirstYes,makeReturn,formatCard} from '?asset=gram';\nimport {proposeGramCrossing} from '?asset=reentry';\n\nconst $=(id)=>document.getElementById(id);\nconst value=(id)=>$(id).value.trim();\nconst tell=(id,msg)=>{$(id).textContent=msg;};\nlet gram=null,plan=null,returned=null,handoff=null;\nconst tableNonce=new URLSearchParams(location.hash.slice(1)).get('returnToTable');\nconst tableReturnMode=!!(window.opener&&tableNonce&&/^[a-f0-9]{32}$/.test(tableNonce));\nconst TABLE_MESSAGE='bananagram.reviewed-seat-draft/v0';\nif(tableReturnMode){\n $('returnToTableBtn').hidden=false;\n $('tableReturnHint').hidden=false;\n}\nfunction syncReturnButton(){\n $('returnToTableBtn').disabled=!tableReturnMode||!handoff;\n}\nconst newRef=()=>{\n const u=crypto.randomUUID?.();\n if(u) return 'gram:'+u;\n const bytes=crypto.getRandomValues(new Uint8Array(16));\n return 'gram:'+Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('');\n};\nfunction privateDownload(filename,body){\n const blob=new Blob([body],{type:'application/json;charset=utf-8'});\n const url=URL.createObjectURL(blob),a=document.createElement('a');\n a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();\n setTimeout(()=>URL.revokeObjectURL(url),1200);\n}\nfunction invalidateDownstream(){\n plan=null;returned=null;handoff=null;\n tell('firstYesPreview','This Gram has changed. Select a fresh First Yes plan if useful.');\n tell('returnPreview','This Gram has changed. A return must reference the latest revision.');\n tell('crossPreview','The Gram has changed. Review and prepare another redaction if you want to export it.');\n $('downloadHandoff').disabled=true;syncReturnButton();\n tell('crossStatus','');\n}\nfunction updateList(id,items,formatter){\n const root=$(id);\n root.replaceChildren();\n if(!items.length){const p=document.createElement('p');p.className='hint';p.textContent='None recorded yet.';root.append(p);return;}\n items.forEach((v,i)=>{\n const div=document.createElement('div');div.textContent=(i+1)+'. '+formatter(v);root.append(div);\n });\n}\nfunction render(){\n $('savePrivate').disabled=!gram;\n if(!gram){tell('gramPreview','Start by planting a question. The Gram stays in this page until you explicitly download it.');updateList('traceList',[],()=> '');updateList('tensionList',[],()=> '');return;}\n tell('gramPreview',formatCard(gram,returned));\n updateList('traceList',gram.trace,x=>x.statement+' — '+x.sourceType.replaceAll('_',' '));\n updateList('tensionList',gram.tensions,x=>x.oneView+' / '+x.otherView+' · OPEN: '+x.unresolvedQuestion);\n}\nfunction grow(fn){\n if(!gram){tell('observeStatus','Plant your Gram first.');return;}\n try{gram=fn(gram);invalidateDownstream();render();tell('observeStatus','Preserved a new local revision ('+gram.revision+'). Your earlier snapshot was not silently overwritten.');}\n catch(err){tell('observeStatus',err.message||'Could not update Gram.');}\n}\n$('startForm').addEventListener('submit',e=>{\n e.preventDefault();\n if(!$('startForm').reportValidity())return;\n try{\n  const first=createGram({sourceRef:newRef(),kind:'question',\n   need:value('need'),offeringBack:value('offering'),ifThisSucceeds:value('possible'),question:value('question')});\n  if(gram&&!confirm('Replace your current unsaved Gram with a new one? Download it privately first if you want to keep it.'))return;\n  gram=first;invalidateDownstream();render();\n  tell('startStatus','Gram planted on this device. Revision 1. No contact, promise, or outside record created.');\n }catch(err){tell('startStatus',err.message||'Could not create Gram.');}\n});\n$('starter').addEventListener('click',()=>{\n $('need').value='Could a willing food shelf buyer benefit from a verified comparison of milk sourcing options?';\n $('offering').value='If helpful, share a public-safe research method with other communities, subject to consent.';\n $('possible').value='An authorized buyer can choose a suitable option without relying on rumors or guessed prices.';\n $('question').value='Which program, quantities, conditions and dates are currently verified?';\n tell('startStatus','Fictional research starter loaded. It is not a claim about an actual food shelf.');\n});\n$('fresh').addEventListener('click',()=>{\n if(gram&&!confirm('Start fresh? Unsaved work in this browser page will be lost.'))return;\n gram=null;plan=null;returned=null;handoff=null;\n for(const form of ['startForm','traceForm','tensionForm','firstYesForm','returnForm','crossForm'])$(form).reset();\n $('downloadHandoff').disabled=true;syncReturnButton();\n for(const id of ['startStatus','observeStatus','firstYesStatus','returnStatus','crossStatus'])tell(id,'');\n tell('firstYesPreview','Your chosen plan will appear here. Selecting is not executing, purchasing, scheduling, enrolling, or confirming anything.');\n tell('returnPreview','A return does not create another task or transfer authority.');\n tell('crossPreview','Nothing crosses automatically. An authorized person would still need to accept the proposal.');\n render();\n});\n$('traceForm').addEventListener('submit',e=>{\n e.preventDefault();if(!e.target.reportValidity())return;\n grow(g=>addTrace(g,{statement:value('trace'),sourceType:value('traceType')}));\n e.target.reset();\n});\n$('tensionForm').addEventListener('submit',e=>{\n e.preventDefault();if(!e.target.reportValidity())return;\n grow(g=>addTension(g,{oneView:value('oneView'),otherView:value('otherView'),unresolvedQuestion:value('unresolved')}));\n e.target.reset();\n});\n$('firstYesForm').addEventListener('submit',e=>{\n e.preventDefault();if(!gram){tell('firstYesStatus','Plant a Gram first.');return;}\n if(!e.target.reportValidity())return;\n try{\n  plan=selectFirstYes(gram,{selected:true,prepareNow:value('prepare'),\n   permissionQuestion:value('permission'),proofOfReturn:value('proof')});\n  tell('firstYesPreview',JSON.stringify(plan,null,2));\n  tell('firstYesStatus','Plan selected locally. No task assigned, message sent, or authorization granted.');\n }catch(err){tell('firstYesStatus',err.message);}\n});\n$('returnForm').addEventListener('submit',e=>{\n e.preventDefault();if(!gram){tell('returnStatus','Plant a Gram first.');return;}\n try{\n  returned=makeReturn(gram,{reviewed:true,fruit:value('fruit'),seed:value('seed'),compost:value('compost')});\n  tell('returnPreview',JSON.stringify(returned,null,2));\n  tell('returnStatus','Your local account of fruit, seed and compost is saved in this page. No claim of independent verification.');\n  render();\n }catch(err){tell('returnStatus',err.message);}\n});\n$('crossForm').addEventListener('submit',e=>{\n e.preventDefault();\n if(!gram){tell('crossStatus','Plant your Gram first.');return;}\n if(!e.target.reportValidity())return;\n try{\n  const result=proposeGramCrossing(gram,{\n   participationConfirmedByAuthor:$('authorOwn').checked,\n   consentToExport:$('consent').checked,\n   reviewedByHuman:$('reviewed').checked,\n   redactedSummary:value('redaction'),kind:'question',destination:value('destination')\n  });\n  handoff=result.standing==='PROPOSE_ONLY'?result:null;\n  tell('crossPreview',JSON.stringify(result,null,2));\n  $('downloadHandoff').disabled=!handoff;syncReturnButton();\n  tell('crossStatus',handoff?'A proposal-only packet is ready. Download it deliberately if you choose. No message has been sent.':\n   'HOLD: author submission, export consent and redaction review are all required.');\n }catch(err){handoff=null;$('downloadHandoff').disabled=true;syncReturnButton();tell('crossStatus',err.message||'Unable to prepare redaction.');}\n});\n$('savePrivate').addEventListener('click',()=>{\n if(!gram)return;\n if(!confirm('Download the COMPLETE PRIVATE Gram? It may include unverified statements or personal notes. Do not publish or forward this raw file.'))return;\n const out={schema:'bananagram.private-local-export/v0',\n  warning:'PRIVATE DEVICE EXPORT; not a public proposal or independently verified Jubilee receipt',\n  gram,firstYesPlan:plan,localReturn:returned};\n privateDownload('bananagram-private-'+gram.sourceRef.replace(/[^a-z0-9-]/gi,'-')+'.json',JSON.stringify(out,null,2));\n tell('startStatus','Private draft downloaded to your device; it was not uploaded or sent.');\n});\n$('downloadHandoff').addEventListener('click',()=>{\n if(!handoff)return;\n // Re-check that this remains the particular reviewed redaction.\n const current=proposeGramCrossing(gram,{participationConfirmedByAuthor:$('authorOwn').checked,\n   consentToExport:$('consent').checked,reviewedByHuman:$('reviewed').checked,\n   redactedSummary:value('redaction'),kind:'question',destination:value('destination')});\n if(current.standing!=='PROPOSE_ONLY'||JSON.stringify(current)!==JSON.stringify(handoff)){\n  handoff=null;$('downloadHandoff').disabled=true;syncReturnButton();\n  tell('crossStatus','Something changed. Review and prepare the redaction again.');return;\n }\n privateDownload('bananagram-reviewed-proposal.json',JSON.stringify(handoff,null,2));\n tell('crossStatus','Proposal packet downloaded locally. No message or submission was sent.');\n});\nfor(const id of ['redaction','destination','authorOwn','consent','reviewed']){\n $(id).addEventListener('input',()=>{\n  handoff=null;$('downloadHandoff').disabled=true;syncReturnButton();\n  tell('crossStatus','Draft changed; prepare and review again before exporting.');\n });\n}\n$('returnToTableBtn').addEventListener('click',()=>{\n if(!tableReturnMode||!handoff||!window.opener||window.opener.closed){\n  tell('crossStatus','Your original Table tab is not available. Keep this private draft and use its separate download if you want.');\n  return;\n }\n try{\n  const current=proposeGramCrossing(gram,{\n   participationConfirmedByAuthor:$('authorOwn').checked,\n   consentToExport:$('consent').checked,\n   reviewedByHuman:$('reviewed').checked,\n   redactedSummary:value('redaction'),kind:'question',destination:value('destination')\n  });\n  if(current.standing!=='PROPOSE_ONLY'||JSON.stringify(current)!==JSON.stringify(handoff))\n   throw Error('The reviewed draft changed. Prepare it again first.');\n  const summary=current.candidate?.summary;\n  if(typeof summary!=='string'||summary.length<12||summary.length>240)\n   throw Error('Only a short reviewed question can return to the Table.');\n  window.opener.postMessage({type:TABLE_MESSAGE,nonce:tableNonce,\n    standing:'PROPOSE_ONLY',summary},location.origin);\n  tell('crossStatus','The reviewed question was offered to your original Table tab as an editable draft. No contribution was saved or shared.');\n }catch(err){tell('crossStatus',err.message||'Unable to return the draft.');}\n});\n$('printPrivate').addEventListener('click',()=>window.print());\nrender();\n";
export const GRAM = "// BANANAGRAM PORTABLE-001 · no network, auth, ledger writes, or public posting.\nexport const GRAM='bananagram.portable-proposal/v0';\nexport const RETURN='bananagram.local-return/v0';\nexport const LINKS=Object.freeze(['makes_possible','learned_from','grafted_into','left_behind','composted_into','harvested_by']);\nconst REFS=/^[a-z][a-z0-9:_-]{7,95}$/;\nconst KINDS=new Set(['need','question','offer','experiment']);\nconst SOURCES=new Set(['heard_from_someone','observed_by_author','document_unreviewed','local_test']);\nconst safe=(v,min=0,max=500)=>{\n if(typeof v!=='string')throw Error('TEXT_REQUIRED');\n const s=v.replace(/[\\x00-\\x1f\\x7f]/g,' ').trim().replace(/\\s+/g,' ');\n if(s.length<min||s.length>max)throw Error('TEXT_LENGTH');\n return s;\n};\nconst ref=(v)=>{if(typeof v!=='string'||!REFS.test(v))throw Error('OPAQUE_REFERENCE_REQUIRED');return v;};\nconst copy=(v)=>JSON.parse(JSON.stringify(v));\nconst check=(v)=>{if(!v||v.schema!==GRAM||v.standing!=='LOCAL_PROPOSAL')throw Error('INVALID_GRAM');};\nconst append=(g,key,v)=>{check(g);const out=copy(g);out.previousRevision=g.revision;out.revision++;out[key].push(v);return out;};\nexport function createGram({sourceRef,kind='question',need,offeringBack='',ifThisSucceeds,question=''}){\n if(!KINDS.has(kind))throw Error('INVALID_KIND');\n return {schema:GRAM,standing:'LOCAL_PROPOSAL',scope:'this-device',sourceRef:ref(sourceRef),\n  revision:1,previousRevision:null,kind,need:safe(need,12,500),offeringBack:safe(offeringBack,0,240),\n  ifThisSucceeds:safe(ifThisSucceeds,12,300),question:safe(question,0,300),\n  reciprocity:'VOLUNTARY_NOT_REQUIRED',trace:[],tensions:[],relations:[],\n  authority:{actorAuthenticated:false,stewardAccepted:false,canonicalWrite:false,\n    transportSent:false,delivered:false,published:false}};\n}\nexport function addTrace(g,{statement,sourceType='heard_from_someone',sourceRef=null}){\n if(!SOURCES.has(sourceType))throw Error('INVALID_TRACE_TYPE');\n return append(g,'trace',{statement:safe(statement,12,450),sourceType,\n  sourceRef:sourceRef?ref(sourceRef):null,standing:'REPORTED_NOT_CONFIRMED'});\n}\nexport function addTension(g,{oneView,otherView,unresolvedQuestion}){\n return append(g,'tensions',{oneView:safe(oneView,10,320),otherView:safe(otherView,10,320),\n   unresolvedQuestion:safe(unresolvedQuestion,10,320),standing:'OPEN_NOT_RESOLVED'});\n}\nexport function linkNearby(g,{verb,targetRef,why}){\n if(!LINKS.includes(verb))throw Error('INVALID_BANANAGRAM_LINK');\n const target=ref(targetRef);\n if(target===g.sourceRef)throw Error('SELF_LINK_REFUSED');\n return append(g,'relations',{verb,targetRef:target,why:safe(why,12,240),\n   standing:'LOCAL_CANDIDATE',freeGraphAdmitted:false});\n}\nexport function selectFirstYes(g,{selected,prepareNow,permissionQuestion,proofOfReturn}){\n check(g);\n if(selected!==true)return {schema:'bananagram.first-yes/v0',standing:'HOLD_SELECTION_REQUIRED'};\n return {schema:'bananagram.first-yes/v0',standing:'SELECTED_PLAN_ONLY',sourceRef:g.sourceRef,\n  revision:g.revision,prepareNow:safe(prepareNow,12,320),\n  permissionQuestion:safe(permissionQuestion,12,320),\n  proofOfReturn:safe(proofOfReturn,12,320),\n  authority:{execute:false,stewardPermission:false,canonicalReceipt:false,notifications:false}};\n}\nexport function makeReturn(g,{reviewed,fruit='',seed='',compost=''}){\n check(g);\n if(reviewed!==true)return {schema:RETURN,standing:'HOLD_HUMAN_REVIEW_REQUIRED'};\n const a=safe(fruit,0,300),b=safe(seed,0,300),c=safe(compost,0,300);\n if(!a&&!b&&!c)throw Error('EMPTY_RETURN');\n return {schema:RETURN,standing:'AUTHOR_REPORTED_LOCAL_RETURN',sourceRef:g.sourceRef,\n  revision:g.revision,fruit:{text:a,evidence:'SELF_REPORT',confirmed:false},\n  seed:{text:b,selectionAuthority:false,crossingAuthority:false},\n  compost:{text:c,authority:false},openTensions:g.tensions.length,\n  consequenceReceipt:null,successorTableInvite:null};\n}\nexport function formatCard(g,ret=null){\n check(g);\n if(ret && (ret.schema!==RETURN||ret.sourceRef!==g.sourceRef||ret.revision!==g.revision))\n   throw Error('STALE_OR_WRONG_RETURN');\n const lines=['BANANAGRAM · PRIVATE, UNSENT PROPOSAL','Revision '+g.revision,\n '', 'NEEDS',g.need,'',\n 'OFFERING BACK (VOLUNTARY; NEVER OWED)',g.offeringBack||'None specified','',\n 'IF THIS SUCCEEDS, WHAT BECOMES POSSIBLE NEXT?',g.ifThisSucceeds,'',\n 'QUESTION',g.question||'Unknown','',\n 'TRACES — NOT CONFIRMED',...g.trace.map(t=>'- '+t.statement+' ['+t.sourceType+']'),'',\n 'TENSIONS — KEEP BOTH PERSPECTIVES',...g.tensions.map(t=>'- '+t.oneView+' / '+t.otherView+' · '+t.unresolvedQuestion),'',\n 'POSSIBLE LINKS — NOT FREE GRAPH ADMISSIONS',...g.relations.map(x=>'- '+x.verb+' → '+x.targetRef+': '+x.why)];\n if(ret)lines.push('','RETURN — '+ret.standing,'FRUIT (AUTHOR REPORT): '+ret.fruit.text,\n   'SEED (NOT SELECTED): '+ret.seed.text,'COMPOST: '+ret.compost.text);\n lines.push('','No message sent. No Jubilee receipt. No partner enrolled. No verified delivery.');\n return lines.join('\\n');\n}\n";
export const PARTICIPATION = "/** Illustrative, PURE boundary; no network, no database, no Telegram or authority writes. */\nexport const VERSION = 'graft/participation-bridge-candidate-v0';\nconst TOKEN = /(?:^|[^\\w])(?:[A-Za-z0-9_-]{43})(?:$|[^\\w])/;\nconst CONTACT = /[\\w.+-]+@[\\w.-]+\\.[A-Za-z]{2,}|(?:\\+?1[ .-]?)?\\(?\\d{3}\\)?[ .-]?\\d{3}[ .-]?\\d{4}|https?:\\/\\/|www\\./i;\nconst DESTINATIONS = new Set(['campfire-review','telegram-porch-draft','first-yes']);\nconst KINDS = new Set(['question','need','offer','experiment']);\nfunction clean(t, max){\n if(typeof t !== 'string') throw new TypeError('TEXT_REQUIRED');\n const v=t.replace(/[\\x00-\\x1f\\x7f]/g,' ').replace(/\\s+/g,' ').trim();\n if(v.length<12||v.length>max) throw new TypeError('TEXT_LENGTH');\n if(CONTACT.test(v)||TOKEN.test(v)) throw new TypeError('PRIVATE_CONTENT_REFUSED');\n return v;\n}\n/**\n * input: {sourceRef, status, kind, destination, redactedSummary,\n *         consentToExport, reviewedByHuman, sourceVisibility}\n * The source record is NEVER copied; passed redactedSummary must be separately\n * consented and reviewed. No source invite URLs or secret tokens are accepted.\n */\nexport function prepareCandidate(input) {\n if(!input || typeof input !== 'object' || Array.isArray(input))throw new TypeError('OBJECT_REQUIRED');\n if(typeof input.sourceRef!=='string' || !/^[a-z0-9:-]{8,96}$/.test(input.sourceRef))throw new TypeError('OPAQUE_REFERENCE_REQUIRED');\n if(input.status!=='participating')return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'NOT_AN_ACTIVE_CONTRIBUTION'});\n if(input.consentToExport!==true)return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'NO_EXPORT_CONSENT'});\n if(input.reviewedByHuman!==true)return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'NEEDS_HUMAN_REVIEW'});\n if(input.sourceVisibility!=='eligible-for-explicit-export')return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:'SOURCE_SCOPE_REFUSES_EXPORT'});\n if(!DESTINATIONS.has(input.destination)||!KINDS.has(input.kind))throw new TypeError('UNSUPPORTED_SEAM');\n const summary=clean(input.redactedSummary,240);\n return Object.freeze({\n  schema:VERSION,\n  standing:'PROPOSE_ONLY',\n  source:{opaqueRef:input.sourceRef,veracity:'UNVERIFIED_SELF_REPORT',scope:'REVIEWED_REDACTION'},\n  target:input.destination,\n  candidate:{kind:input.kind,summary},\n  authority:{actorAuthenticated:false,circleMembership:false,consentToPerform:false,\n    canonicalWrite:false,transportDispatched:false,partnerCommitted:false,\n    provisionConfirmed:false,publicationApproved:false},\n  nextGate:'A separately authenticated, authorized human must choose whether and where to submit this proposal.'\n });\n}\n";
export const REENTRY = "import {GRAM} from '?asset=gram';\nimport {prepareCandidate,VERSION} from '?asset=participation';\n/** Explicit consented, human-reviewed Gram -> inert proposal crossing. */\nexport function proposeGramCrossing(gram,{\n participationConfirmedByAuthor=false,consentToExport=false,\n reviewedByHuman=false,redactedSummary='',kind='question',destination='first-yes'\n}={}){\n if(!gram||gram.schema!==GRAM||gram.scope!=='this-device'||gram.standing!=='LOCAL_PROPOSAL')\n   throw Error('INVALID_SOURCE_GRAM');\n if(!Number.isInteger(gram.revision)||gram.revision<1)throw Error('INVALID_GRAM_REVISION');\n if(!participationConfirmedByAuthor||!consentToExport||!reviewedByHuman)\n  return Object.freeze({schema:VERSION,standing:'HOLD_LOCAL',why:\n    !participationConfirmedByAuthor?'NO_AUTHOR_SUBMISSION':\n    !consentToExport?'NO_EXPORT_CONSENT':'NEEDS_HUMAN_REVIEW'});\n const sourceRef=gram.sourceRef+':r'+gram.revision;\n // IMPORTANT: no automatic copying of need, offeringBack, trace, tension,\n // relation, personal history, or link token. A new redaction is required.\n return prepareCandidate({sourceRef,status:'participating',consentToExport:true,\n  reviewedByHuman:true,sourceVisibility:'eligible-for-explicit-export',\n  redactedSummary,kind,destination});\n}\n";
